using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var allGOs = Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None);
        result.Log("Total GameObjects in scene: {0}", allGOs.Length);
        foreach (var go in allGOs.Where(g => g.transform.parent == null))
        {
            result.Log("Root GO: {0}", go.name);
        }

        var animators = Object.FindObjectsByType<Animator>(FindObjectsSortMode.None);
        foreach (var anim in animators)
        {
            result.Log("Animator on '{0}', avatar: {1}, controller: {2}", 
                anim.gameObject.name, 
                anim.avatar != null ? anim.avatar.name : "null", 
                anim.runtimeAnimatorController != null ? anim.runtimeAnimatorController.name : "null");
        }
    }
}

