using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var roots = UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects();
        foreach (var r in roots)
        {
            var anim = r.GetComponent<Animator>();
            if (anim != null)
            {
                result.Log("Root '{0}': Avatar={1}, Controller={2}, Pos={3}, ChildCount={4}", 
                    r.name, 
                    anim.avatar ? anim.avatar.name : "null",
                    anim.runtimeAnimatorController ? anim.runtimeAnimatorController.name : "null",
                    r.transform.position,
                    r.transform.childCount);
                for (int i = 0; i < r.transform.childCount; i++)
                {
                    var c = r.transform.GetChild(i);
                    result.Log("   -> Child {0}: {1}", i, c.name);
                }
            }
        }
    }
}

