internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] paths = new string[] {
            "Assets/Models/trump.fbx",
            "Assets/trump.fbx",
            "Assets/Selected/Frank_Damages/Demo/Models/Frank_Mesh_Unity.fbx",
            "Assets/Selected/Frank_Damages/Demo/Models/Frank_Fighting3_Body_LOD.fbx"
        };

        foreach (var p in paths)
        {
            var importer = AssetImporter.GetAtPath(p) as ModelImporter;
            if (importer != null)
            {
                result.Log("Model: {0}\n  animationType: {1}\n  avatarSetup: {2}\n  sourceAvatar: {3}\n  humanDescription isValid: {4}",
                    p, importer.animationType, importer.avatarSetup, 
                    importer.sourceAvatar != null ? importer.sourceAvatar.name : "null",
                    importer.humanDescription.human != null ? importer.humanDescription.human.Length.ToString() : "0");
            }
            else
            {
                result.Log("Importer null for: {0}", p);
            }
        }
    }
}

