using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Check trump.fbx importer
        var importer = AssetImporter.GetAtPath("Assets/Models/trump.fbx") as ModelImporter;
        if (importer != null)
        {
            result.Log("Assets/Models/trump.fbx:\n  animType: {0}, avatarSetup: {1}\n  optimizeGameObjects: {2}", 
                importer.animationType, importer.avatarSetup, importer.optimizeGameObjects);
        }

        var importer2 = AssetImporter.GetAtPath("Assets/trump.fbx") as ModelImporter;
        if (importer2 != null)
        {
            result.Log("Assets/trump.fbx:\n  animType: {0}, avatarSetup: {1}\n  optimizeGameObjects: {2}", 
                importer2.animationType, importer2.avatarSetup, importer2.optimizeGameObjects);
        }

        // Check trumpAvatar
        var trumpAvatar = AssetDatabase.LoadAssetAtPath<Avatar>("Assets/Models/trump.fbx");
        if (trumpAvatar == null)
        {
            var assets = AssetDatabase.LoadAllAssetsAtPath("Assets/Models/trump.fbx");
            foreach (var a in assets)
            {
                if (a is Avatar av) { trumpAvatar = av; break; }
            }
        }
        result.Log("trumpAvatar: {0}, isValid: {1}, isHuman: {2}", 
            trumpAvatar != null ? trumpAvatar.name : "null",
            trumpAvatar != null ? trumpAvatar.isValid.ToString() : "false",
            trumpAvatar != null ? trumpAvatar.isHuman.ToString() : "false");

        // Check weapon bindings in Frank_Damage@Damage_Critical_2Handed, Spear, Assassin
        string[] testNames = new string[] {
            "Frank_Damage@Damage_Critical_2Handed",
            "Frank_Damage@Damage_Critical_Assassin",
            "Frank_Damage@Damage_Critical_Spear",
            "Frank_Damage_2Handed_Hit",
            "Frank_Damage_Assassin_Hit",
            "Frank_Damage_Spear_Hit"
        };

        foreach (var name in testNames)
        {
            var go = GameObject.Find(name);
            if (go != null)
            {
                var anim = go.GetComponent<Animator>();
                result.Log("GO: {0}, Pos={1}, Rot={2}, Scale={3}, Avatar={4}",
                    go.name, go.transform.position, go.transform.eulerAngles, go.transform.localScale,
                    anim != null && anim.avatar != null ? anim.avatar.name : "null");
            }
        }
    }
}

