internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var twoHanded = GameObject.Find("Frank_Damage@Damage_Critical_2Handed");
        var weapon = twoHanded.transform.Find("SK_Blade_HeavyAXE");
        var smr = weapon.GetComponent<SkinnedMeshRenderer>();
        if (smr != null && smr.rootBone != null)
        {
            result.Log("rootBone name: {0}, path: {1}, pos: {2}", 
                smr.rootBone.name, 
                GetPath(smr.rootBone), 
                smr.rootBone.position);
        }
        else
        {
            result.Log("smr or rootBone is null");
        }

        // Let's search all transforms in twoHanded
        foreach (var t in twoHanded.GetComponentsInChildren<Transform>())
        {
            if (t.name.Contains("Weapon") || t.name.Contains("Hand") || t.name.Contains("root") || t.name.Contains("CC_Base"))
            {
                result.Log("Transform: {0}, parent: {1}, localPos: {2}", t.name, t.parent?.name, t.localPosition);
            }
        }
    }

    string GetPath(Transform t)
    {
        if (t.parent == null) return t.name;
        return GetPath(t.parent) + "/" + t.name;
    }
}

