internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var instance = Object.Instantiate(trumpPrefab);
        instance.transform.position = Vector3.zero;
        instance.transform.rotation = Quaternion.identity;

        result.Log("Trump default root transform: pos={0}, rot={1}, scale={2}", 
            instance.transform.position, instance.transform.eulerAngles, instance.transform.localScale);

        var smr = instance.GetComponentInChildren<SkinnedMeshRenderer>();
        if (smr != null)
        {
            result.Log("Trump SMR: {0}, rootBone={1}, bonesCount={2}", smr.name, smr.rootBone.name, smr.bones.Length);
            result.Log("SMR bounds: center={0}, size={1}", smr.bounds.center, smr.bounds.size);
        }

        // Check root and CC_Base_Hip
        var rootBone = instance.transform.Find("root");
        if (rootBone != null)
        {
            result.Log("rootBone localPos={0}, localEuler={1}", rootBone.localPosition, rootBone.localEulerAngles);
            var hip = rootBone.Find("CC_Base_Hip");
            if (hip != null)
            {
                result.Log("hip localPos={0}, localEuler={1}", hip.localPosition, hip.localEulerAngles);
                var pelvis = hip.Find("CC_Base_Pelvis");
                var waist = hip.Find("CC_Base_Waist");
                result.Log("pelvis localPos={0}, localEuler={1}", pelvis?.localPosition, pelvis?.localEulerAngles);
                result.Log("waist localPos={0}, localEuler={1}", waist?.localPosition, waist?.localEulerAngles);
            }
        }

        // Also check if animator is on instance
        var anim = instance.GetComponent<Animator>();
        result.Log("Instance Animator: avatar={0}, isHuman={1}", 
            anim != null && anim.avatar != null ? anim.avatar.name : "null",
            anim != null ? anim.isHuman.ToString() : "null");

        Object.DestroyImmediate(instance);
    }
}

