internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var importer = AssetImporter.GetAtPath("Assets/Models/trump.fbx") as ModelImporter;
        var desc = importer.humanDescription;
        result.Log("Root bone in humanDescription: {0}", desc.skeleton.Length > 0 ? desc.skeleton[0].name : "none");

        // Let's check what Avatar.isValid and what Unity's Avatar lookup does
        var trump = GameObject.Find("Frank_Damage@Damage_Critical_2Handed");
        var anim = trump.GetComponent<Animator>();

        // Let's check GetBoneTransform on Animator
        for (int i = 0; i < (int)HumanBodyBones.LastBone; i++)
        {
            var bone = (HumanBodyBones)i;
            var t = anim.GetBoneTransform(bone);
            if (t != null && (bone == HumanBodyBones.Hips || bone == HumanBodyBones.Head || bone == HumanBodyBones.RightHand))
            {
                result.Log("anim.GetBoneTransform({0}) = {1} (parent={2})", bone, t.name, t.parent?.name);
            }
            else if (bone == HumanBodyBones.Hips && t == null)
            {
                result.LogError("anim.GetBoneTransform(Hips) is NULL!");
            }
        }
    }
}

