internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var instance = Object.Instantiate(trumpPrefab);

        var leftArm = instance.transform.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_L_Clavicle/CC_Base_L_Upperarm");
        var rightArm = instance.transform.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm");

        result.Log("Left UpperArm rot: {0}, right UpperArm rot: {1}", leftArm.localEulerAngles, rightArm.localEulerAngles);
        result.Log("Left UpperArm world pos: {0}", leftArm.position);

        var leftForearm = leftArm.Find("CC_Base_L_Forearm");
        result.Log("Left Forearm world pos: {0}", leftForearm.position);

        var dir = (leftForearm.position - leftArm.position).normalized;
        result.Log("Left Arm direction vector: {0}", dir);

        // In a true T-pose, the left arm direction from shoulder to elbow should be pointing roughly in (+X, 0, 0) or (-X, 0, 0)
        // Let's check the angle with horizontal (-1, 0, 0) or (+1, 0, 0)
        float angleWithHorizontal = Vector3.Angle(dir, Vector3.left);
        result.Log("Angle with left (-1,0,0): {0} degrees", angleWithHorizontal);

        Object.DestroyImmediate(instance);
    }
}

