using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var twoHanded = GameObject.Find("Frank_Damage@Damage_Critical_2Handed");
        var smr = twoHanded.GetComponentInChildren<SkinnedMeshRenderer>();
        var bakedMesh = new Mesh();
        smr.BakeMesh(bakedMesh);

        var verts = bakedMesh.vertices;
        float minY = float.MaxValue, maxY = float.MinValue;
        Vector3 maxVert = Vector3.zero, minVert = Vector3.zero;

        for (int i = 0; i < verts.Length; i++)
        {
            var worldV = smr.transform.TransformPoint(verts[i]);
            if (worldV.y > maxY) { maxY = worldV.y; maxVert = worldV; }
            if (worldV.y < minY) { minY = worldV.y; minVert = worldV; }
        }

        result.Log("BakeMesh minY={0} (at {1}), maxY={2} (at {3})", minY, minVert, maxY, maxVert);

        // Also check SK_Blade_HeavyAXE
        var axe = twoHanded.transform.Find("SK_Blade_HeavyAXE")?.GetComponent<SkinnedMeshRenderer>();
        if (axe != null)
        {
            var axeMesh = new Mesh();
            axe.BakeMesh(axeMesh);
            float aMinY = float.MaxValue, aMaxY = float.MinValue;
            foreach (var v in axeMesh.vertices)
            {
                var w = axe.transform.TransformPoint(v);
                if (w.y > aMaxY) aMaxY = w.y;
                if (w.y < aMinY) aMinY = w.y;
            }
            result.Log("Axe BakeMesh minY={0}, maxY={1}", aMinY, aMaxY);
        }
    }
}

