using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] controllers = new string[] {
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_2Handed.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_2Handed_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Assassin.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Assassin_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Dual.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Dual_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_GreatSword.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_GreatSword_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Katana.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Katana_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Spear.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Spear_Hit.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Warrior.controller",
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Warrior_Hit.controller"
        };

        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var trumpAvatar = AssetDatabase.LoadAssetAtPath<Avatar>("Assets/Models/trump.fbx");

        var go = Object.Instantiate(trumpPrefab);
        var anim = go.GetComponent<Animator>();
        if (anim == null) anim = go.AddComponent<Animator>();
        anim.avatar = trumpAvatar;

        foreach (var cPath in controllers)
        {
            var rac = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(cPath);
            anim.runtimeAnimatorController = rac;
            var clip = rac.animationClips[0];

            // Sample clip at beginning, middle, and end
            float[] times = new float[] { 0f, clip.length * 0.5f, clip.length * 0.95f };
            foreach (var t in times)
            {
                clip.SampleAnimation(go, t);
                var smr = go.GetComponentInChildren<SkinnedMeshRenderer>();
                var baked = new UnityEngine.Mesh();
                smr.BakeMesh(baked);

                float minY = float.MaxValue, maxY = float.MinValue;
                foreach (var v in baked.vertices)
                {
                    if (v.y < minY) minY = v.y;
                    if (v.y > maxY) maxY = v.y;
                }

                // Also check if any body parts are stretched abnormally
                var neck = anim.GetBoneTransform(HumanBodyBones.Neck);
                var head = anim.GetBoneTransform(HumanBodyBones.Head);
                float headNeckDist = Vector3.Distance(neck.position, head.position);

                if (headNeckDist > 0.35f || minY < -0.6f || maxY > 3.0f)
                {
                    result.LogWarning("Potential issue with '{0}' at t={1:F2}: minY={2:F2}, maxY={3:F2}, headNeckDist={4:F2}",
                        clip.name, t, minY, maxY, headNeckDist);
                }
            }
        }

        result.Log("Tested all 14 animation clips on Trump!");
        Object.DestroyImmediate(go);
    }
}

