internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] pairs = new string[] {
            "Frank_Damage@Damage_Critical_2Handed",
            "Frank_Damage@Damage_Critical_Assassin",
            "Frank_Damage@Damage_Critical_Dual",
            "Frank_Damage@Damage_Critical_GreatSword",
            "Frank_Damage@Damage_Critical_Katana",
            "Frank_Damage@Damage_Critical_Spear",
            "Frank_Damage@Damage_Critical_Warrior"
        };

        foreach (var p in pairs)
        {
            var go = GameObject.Find(p);
            result.Log("=== {0} ===", p);
            foreach (var t in go.GetComponentsInChildren<Transform>())
            {
                if (t == go.transform) continue;
                if (t.name.Contains("Mesh_Unity") || t.name.Contains("Pants") || t.name.Contains("Cloak") || t.name.Contains("temp") || t.name == "root" || t.name == "trump") continue;
                var smr = t.GetComponent<SkinnedMeshRenderer>();
                var mf = t.GetComponent<MeshFilter>();
                if (smr != null || mf != null)
                {
                    result.Log("  Weapon: {0}, SMR={1}, MF={2}, parent={3}, rootBone={4}",
                        t.name, smr != null, mf != null, t.parent.name, smr?.rootBone?.name);
                }
            }
        }
    }
}

