        playableOutput.SetSourcePlayable(clipPlayable);

        graph.Evaluate(0.5f);
        var handPos0 = anim.GetBoneTransform(HumanBodyBones.RightHand).position;
        graph.Evaluate(1.0f);
        var handPos1 = anim.GetBoneTransform(HumanBodyBones.RightHand).position;

