using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var fbx2H = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Selected/Frank_Damages/Asset/Meshes/Frank_Damage@Damage_Critical_2Handed.FBX");
        var frankInst = Object.Instantiate(fbx2H);
        var fAnim = frankInst.GetComponent<Animator>();

        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var trumpInst = Object.Instantiate(trumpPrefab);
        var tAnim = trumpInst.GetComponent<Animator>();

        var rac = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_2Handed.controller");
        var clip = rac.animationClips[0];

        HumanBodyBones[] testBones = new HumanBodyBones[] {
            HumanBodyBones.Hips, HumanBodyBones.Head,
            HumanBodyBones.LeftHand, HumanBodyBones.RightHand,
            HumanBodyBones.LeftFoot, HumanBodyBones.RightFoot
        };

        float[] sampleTimes = new float[] { 0.5f, 2.0f, 4.0f };

        foreach (var t in sampleTimes)
        {
            clip.SampleAnimation(frankInst, t);
            clip.SampleAnimation(trumpInst, t);

            result.Log("--- At t={0:F1}s ---", t);
            foreach (var b in testBones)
            {
                var fPos = fAnim.GetBoneTransform(b).position;
                var tPos = tAnim.GetBoneTransform(b).position;
                result.Log("Bone {0}: Frank={1}, Trump={2}, diff={3:F2}",
                    b, fPos, tPos, Vector3.Distance(fPos, tPos));
            }
        }

        Object.DestroyImmediate(frankInst);
        Object.DestroyImmediate(trumpInst);
    }
}

