internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var fbx2H = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Selected/Frank_Damages/Asset/Meshes/Frank_Damage@Damage_Critical_2Handed.FBX");
        var axe = fbx2H.transform.Find("SK_Blade_HeavyAXE")?.GetComponent<SkinnedMeshRenderer>();
        var animF = fbx2H.GetComponent<Animator>();
        var rHandF = animF.GetBoneTransform(HumanBodyBones.RightHand);

        // Find R_Weapon_Bone
        Transform rWeaponBone = null;
        foreach (var t in fbx2H.transform.Find("root").GetComponentsInChildren<Transform>())
        {
            if (t.name == "R_Weapon_Bone") { rWeaponBone = t; break; }
        }

        result.Log("FBX 2Handed:");
        result.Log("  rHandF pos: {0}, rot: {1}", rHandF.position, rHandF.eulerAngles);
        result.Log("  rWeaponBone pos: {0}, rot: {1}", rWeaponBone.position, rWeaponBone.eulerAngles);
        result.Log("  offset pos: {0}, offset rot: {1}",
            rHandF.InverseTransformPoint(rWeaponBone.position),
            (Quaternion.Inverse(rHandF.rotation) * rWeaponBone.rotation).eulerAngles);
    }
}

