using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trumpAvatar = AssetDatabase.LoadAssetAtPath<Avatar>("Assets/Models/trump.fbx");
        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");

        string[] victimNames = new string[] {
            "Frank_Damage_Dual_Hit",
            "Frank_Damage_GreatSword_Hit",
            "Frank_Damage_Katana_Hit",
            "Frank_Damage_Warrior_Hit"
        };

        foreach (var name in victimNames)
        {
            var go = GameObject.Find(name);
            if (go == null) continue;

            result.RegisterObjectModification(go);

            // Remove existing mesh children (Frank_Fighting3_Body_LOD, root, etc.)
            for (int i = go.transform.childCount - 1; i >= 0; i--)
            {
                var child = go.transform.GetChild(i).gameObject;
                result.DestroyObject(child);
            }

            // Instantiate trump model as child
            var trump = Object.Instantiate(trumpPrefab, go.transform);
            trump.name = "trump";
            trump.transform.localPosition = Vector3.zero;
            trump.transform.localRotation = Quaternion.identity;
            trump.transform.localScale = Vector3.one;

            // Remove animator from child trump if any
            var childAnim = trump.GetComponent<Animator>();
            if (childAnim != null) Object.DestroyImmediate(childAnim);

            // Configure root animator
            var anim = go.GetComponent<Animator>();
            if (anim != null)
            {
                result.RegisterObjectModification(anim);
                anim.avatar = trumpAvatar;
                anim.applyRootMotion = true;
                anim.cullingMode = AnimatorCullingMode.AlwaysAnimate;
            }

            result.Log("Replaced {0} with Trump model and avatar!", name);
        }
    }
}

