                trump.name = "trump";
                trump.transform.localPosition = Vector3.zero;
                trump.transform.localRotation = Quaternion.identity;
                trump.transform.localScale = Vector3.one;
                // Remove animator from child trump if any
                var childAnim = trump.GetComponent<Animator>();
                if (childAnim != null)
                    Object.DestroyImmediate(childAnim);
                // Configure root animator
                var anim = go.GetComponent<Animator>();
                if (anim != null)
