        var wClip = wAnim.runtimeAnimatorController.animationClips[0];
        for (float t = 0f; t <= 3f; t += 1f)
        {
            wClip.SampleAnimation(warrior, t);
            var rHand = wAnim.GetBoneTransform(HumanBodyBones.RightHand);
            var lHand = wAnim.GetBoneTransform(HumanBodyBones.LeftHand);
            var sword = warrior.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();
