internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        result.Log("Play Mode Active: {0}", EditorApplication.isPlaying);

        var pairs = new (string attacker, string victim)[] {
            ("Frank_Damage@Damage_Critical_2Handed", "Frank_Damage_2Handed_Hit"),
            ("Frank_Damage@Damage_Critical_Assassin", "Frank_Damage_Assassin_Hit"),
            ("Frank_Damage@Damage_Critical_Dual", "Frank_Damage_Dual_Hit"),
            ("Frank_Damage@Damage_Critical_GreatSword", "Frank_Damage_GreatSword_Hit"),
            ("Frank_Damage@Damage_Critical_Katana", "Frank_Damage_Katana_Hit"),
            ("Frank_Damage@Damage_Critical_Spear", "Frank_Damage_Spear_Hit"),
            ("Frank_Damage@Damage_Critical_Warrior", "Frank_Damage_Warrior_Hit")
        };

        foreach (var p in pairs)
        {
            var atk = GameObject.Find(p.attacker);
            var vic = GameObject.Find(p.victim);

            var aAnim = atk?.GetComponent<Animator>();
            var vAnim = vic?.GetComponent<Animator>();

            var aHips = aAnim?.GetBoneTransform(HumanBodyBones.Hips);
            var vHips = vAnim?.GetBoneTransform(HumanBodyBones.Hips);

            var aState = aAnim?.GetCurrentAnimatorStateInfo(0);
            var vState = vAnim?.GetCurrentAnimatorStateInfo(0);

            result.Log("Pair: [{0}] vs [{1}]\n  Atk pos={2}, hips={3}, normTime={4:F2}\n  Vic pos={5}, hips={6}, normTime={7:F2}",
                atk.name, vic.name,
                atk.transform.position, aHips?.position, aState.HasValue ? aState.Value.normalizedTime : -1f,
                vic.transform.position, vHips?.position, vState.HasValue ? vState.Value.normalizedTime : -1f);
        }

        EditorApplication.isPlaying = false;
        result.Log("Play Mode testing finished successfully. Exited play mode.");
    }
}

