internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var fbxSpear = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Selected/Frank_Damages/Asset/Meshes/Frank_Damage@Damage_Critical_Spear.FBX");
        var animF = fbxSpear.GetComponent<Animator>();
        var rac = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Spear.controller");
        var clip = rac.animationClips[0];

