        {
            clip.SampleAnimation(fbxSpear, t);
            var hand = animF.GetBoneTransform(HumanBodyBones.RightHand);
            var spearBone = fbxSpear.transform.Find("root").GetComponentsInChildren<Transform>();
            Transform sRoot = null;
            foreach (var tr in spearBone) if (tr.name == "Spear_Root") { sRoot = tr; break; }
            result.Log(string.Format("Frank Spear t={0:F1}s: hand={1}, sRoot={2}, bounds={3}",
                t, hand.position, sRoot.position, spearSMR.bounds));
        }

        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var trump = Object.Instantiate(trumpPrefab);
        var tAnim = trump.GetComponent<Animator>();
        for (float t = 0f; t <= 2f; t += 1f)
        {
            clip.SampleAnimation(trump, t);
            var hand = tAnim.GetBoneTransform(HumanBodyBones.RightHand);
            result.Log(string.Format("Trump Spear t={0:F1}s: hand={1}", t, hand.position));
        }
        Object.DestroyImmediate(trump);
    }
}

