using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var warrior = GameObject.Find("Frank_Damage@Damage_Critical_Warrior");
        var warriorTrump = warrior.transform.Find("trump");
        var lHand = warriorTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_L_Clavicle/CC_Base_L_Upperarm/CC_Base_L_Forearm/CC_Base_L_Hand");
        var rHand = warriorTrump.Find("root/CC_Base_Hip/CC_Base_Waist/CC_Base_Spine01/CC_Base_Spine02/CC_Base_R_Clavicle/CC_Base_R_Upperarm/CC_Base_R_Forearm/CC_Base_R_Hand");

        var fbxWarrior = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Selected/Frank_Damages/Asset/Meshes/Frank_Damage@Damage_Critical_Warrior.FBX");

        // Find Shield_Root in FBX
        Transform fbxLHandShield = null;
        Transform fbxSwordR = null;
        foreach (var t in fbxWarrior.transform.Find("root").GetComponentsInChildren<Transform>())
        {
            if (t.name == "Lhand_Shield_Bone") fbxLHandShield = t;
            if (t.name == "Sword_R_Bone") fbxSwordR = t;
        }

        // 1. Rebuild Shield bones under lHand
        var existingShieldBone = lHand.Find("Lhand_Shield_Bone");
        if (existingShieldBone != null) result.DestroyObject(existingShieldBone.gameObject);

        // Instantiate clone of Lhand_Shield_Bone hierarchy from FBX
        var clonedShieldHierarchy = Object.Instantiate(fbxLHandShield.gameObject, lHand);
        clonedShieldHierarchy.name = "Lhand_Shield_Bone";
        result.RegisterObjectCreation(clonedShieldHierarchy);
        clonedShieldHierarchy.transform.localPosition = new Vector3(0.05f, 0.05f, -0.01f);
        clonedShieldHierarchy.transform.localEulerAngles = new Vector3(348.75f, 265.85f, 102.72f);

        // 2. Rebuild Sword bones under rHand
        var existingSwordBone = rHand.Find("R_Hand_Weapon");
        if (existingSwordBone != null) result.DestroyObject(existingSwordBone.gameObject);

        var rHandWeapon = new GameObject("R_Hand_Weapon");
        result.RegisterObjectCreation(rHandWeapon);
        rHandWeapon.transform.SetParent(rHand, false);
        rHandWeapon.transform.localPosition = new Vector3(0.09f, -0.06f, 0.0f);
        rHandWeapon.transform.localEulerAngles = new Vector3(5.68f, 36.54f, 83.46f);

        var clonedSwordHierarchy = Object.Instantiate(fbxSwordR.gameObject, rHandWeapon.transform);
        clonedSwordHierarchy.name = "Sword_R_Bone";
        result.RegisterObjectCreation(clonedSwordHierarchy);
        clonedSwordHierarchy.transform.localPosition = Vector3.zero;
        clonedSwordHierarchy.transform.localEulerAngles = Vector3.zero;

        // 3. Collect bones for Shield SMR
        var shieldSMR = warrior.transform.Find("Shield")?.GetComponent<SkinnedMeshRenderer>();
        var fbxShieldSMR = fbxWarrior.transform.Find("Shield")?.GetComponent<SkinnedMeshRenderer>();

        var shieldBoneDict = new System.Collections.Generic.Dictionary<string, Transform>();
        foreach (var t in clonedShieldHierarchy.GetComponentsInChildren<Transform>())
        {
            shieldBoneDict[t.name] = t;
        }

        Transform[] newShieldBones = new Transform[fbxShieldSMR.bones.Length];
        for (int i = 0; i < fbxShieldSMR.bones.Length; i++)
        {
            string bName = fbxShieldSMR.bones[i].name;
            if (shieldBoneDict.TryGetValue(bName, out var targetBone))
            {
                newShieldBones[i] = targetBone;
            }
            else
            {
                result.LogWarning("Shield bone not found: {0}", bName);
            }
        }

        result.RegisterObjectModification(shieldSMR);
        shieldSMR.rootBone = shieldBoneDict["Shield_Root"];
        shieldSMR.bones = newShieldBones;

        // 4. Collect bones for Sword_R SMR
        var swordSMR = warrior.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();
        var fbxSwordSMR = fbxWarrior.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();

        var swordBoneDict = new System.Collections.Generic.Dictionary<string, Transform>();
        foreach (var t in clonedSwordHierarchy.GetComponentsInChildren<Transform>())
        {
            swordBoneDict[t.name] = t;
        }

        Transform[] newSwordBones = new Transform[fbxSwordSMR.bones.Length];
        for (int i = 0; i < fbxSwordSMR.bones.Length; i++)
        {
            string bName = fbxSwordSMR.bones[i].name;
            if (swordBoneDict.TryGetValue(bName, out var targetBone))
            {
                newSwordBones[i] = targetBone;
            }
            else
            {
                result.LogWarning("Sword bone not found: {0}", bName);
            }
        }

        result.RegisterObjectModification(swordSMR);
        swordSMR.rootBone = swordBoneDict["Sword_R_Bone"];
        swordSMR.bones = newSwordBones;

        result.Log("Rebuilt Warrior Shield (25 bones) and Sword (9 bones) successfully!");
    }
}

