        var animDual = fbxDual.GetComponent<Animator>();

        var racDual = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Dual.controller");
        var clipDual = racDual.animationClips[0];

        var racDualHit = AssetDatabase.LoadAssetAtPath<RuntimeAnimatorController>(
            "Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/Critical_Dual_Hit.controller");
        var clipDualHit = racDualHit.animationClips[0];

        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
