    public void Execute(ExecutionResult result)
    {
        var fbx2H = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Selected/Frank_Damages/Asset/Meshes/Frank_Damage@Damage_Critical_2Handed.FBX");
        var animF = fbx2H.GetComponent<Animator>();
        var clip2H = animF.runtimeAnimatorController.animationClips[0];

        var hit2HClip = AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/Selected/Frank_Damages/Asset/Animations/Damages_Critical_Set/hit_combo_weapon(1).anim");

        var trumpPrefab = AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Models/trump.fbx");
        var atk = Object.Instantiate(trumpPrefab);
        var vic = Object.Instantiate(trumpPrefab);

        var atkContainer = new GameObject("AtkContainer");
        atk.transform.SetParent(atkContainer.transform, false);
        var aAnim = atkContainer.AddComponent<Animator>();
        aAnim.avatar = AssetDatabase.LoadAssetAtPath<Avatar>("Assets/Models/trump.fbx");

        var vicContainer = new GameObject("VicContainer");
        vic.transform.SetParent(vicContainer.transform, false);
        var vAnim = vicContainer.AddComponent<Animator>();
        vAnim.avatar = AssetDatabase.LoadAssetAtPath<Avatar>("Assets/Models/trump.fbx");

        atkContainer.transform.position = new Vector3(-18f, 0f, -3.0f);
        atkContainer.transform.rotation = Quaternion.identity;

        // In original demo:
        // Frank_Damage@Damage_Critical_2Handed: pos = (-15.43, 0.00, -3.55), rot = (0, 0, 0)
        // Frank_Damage_2Handed_Hit: pos = (-15.43, 0.00, -2.32), rot = (0, 180, 0)
        // Delta Z was: -2.32 - (-3.55) = +1.23m!
        // At our Atk pos Z = -3.0m, Vic pos Z should be -3.0 + 1.23 = -1.77m (we set -1.2m!)
        // What if Vic pos Z is set so that at t=3.8s, Atk hand meets Vic head?
        // Atk hand Z at t=3.8s is -0.02m.
        // Vic head relative to Vic origin (rot=180) is Z = -(-3.32) = +3.32m.
        // So Vic origin Z + 3.32 = -0.02 => Vic origin Z = -3.34m!
        // Wait, if Vic rot=180:
        // local head Z is negative (-3.32 in world space if rot=0).
        // With rot = 180 (facing back):
        // world Z = Vic_origin_Z - local_Z = Vic_origin_Z - (-3.32) = Vic_origin_Z + 3.32!

        // Let's test different Vic Z positions:
        float[] testVicZ = new float[] { -2.32f, -1.8f, -1.2f, -0.6f, 0.0f, 0.6f };
        foreach (var vz in testVicZ)
        {
            vicContainer.transform.position = new Vector3(-18f, 0f, vz);
            vicContainer.transform.rotation = Quaternion.Euler(0f, 180f, 0f);

            clip2H.SampleAnimation(atkContainer, 3.8f);
            hit2HClip.SampleAnimation(vicContainer, 3.8f);

            var aHand = aAnim.GetBoneTransform(HumanBodyBones.RightHand).position;
            var vHead = vAnim.GetBoneTransform(HumanBodyBones.Head).position;
            var vChest = vAnim.GetBoneTransform(HumanBodyBones.Chest).position;

            result.Log(string.Format("Vic Z={0:F2}: Atk hand Z={1:F2} | Vic chest Z={2:F2}, head Z={3:F2} | dist to head={4:F2}m",
                vz, aHand.z, vChest.z, vHead.z, Vector3.Distance(aHand, vHead)));
        }

        Object.DestroyImmediate(atkContainer);
        Object.DestroyImmediate(vicContainer);
    }
}

