using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        result.Log("Play Mode Active: {0}", EditorApplication.isPlaying);

        // 1. Check Warrior Shield & Sword
        var warrior = GameObject.Find("Frank_Damage@Damage_Critical_Warrior");
        var shield = warrior?.transform.Find("Shield")?.GetComponent<SkinnedMeshRenderer>();
        var sword = warrior?.transform.Find("Sword_R")?.GetComponent<SkinnedMeshRenderer>();
        result.Log("Warrior Shield: isVisible={0}, bounds={1}", shield?.isVisible, shield?.bounds);
        result.Log("Warrior Sword: isVisible={0}, bounds={1}", sword?.isVisible, sword?.bounds);

        // 2. Check Spear Attacker hand vs Spear_Root
        var spear = GameObject.Find("Frank_Damage@Damage_Critical_Spear");
        var sAnim = spear?.GetComponent<Animator>();
        var sHand = sAnim?.GetBoneTransform(HumanBodyBones.RightHand);
        var sRoot = spear?.transform.Find("trump").GetComponentsInChildren<Transform>();
        Transform sr = null;
        foreach (var t in sRoot) if (t.name == "Spear_Root") { sr = t; break; }
        result.Log("Spear: hand pos={0}, Spear_Root pos={1}, dist={2:F3}m",
            sHand?.position, sr?.position,
            (sHand != null && sr != null) ? Vector3.Distance(sHand.position, sr.position) : -1f);

        // 3. Check Dual Attacker vs Victim
        var dualAtk = GameObject.Find("Frank_Damage@Damage_Critical_Dual");
        var dualVic = GameObject.Find("Frank_Damage_Dual_Hit");
        var daAnim = dualAtk?.GetComponent<Animator>();
        var dvAnim = dualVic?.GetComponent<Animator>();
        result.Log("Dual: Atk hips={0}, Vic hips={1}",
            daAnim?.GetBoneTransform(HumanBodyBones.Hips)?.position,
            dvAnim?.GetBoneTransform(HumanBodyBones.Hips)?.position);

        // 4. Check 2Handed Attacker vs Victim
        var twoHAtk = GameObject.Find("Frank_Damage@Damage_Critical_2Handed");
        var twoHVic = GameObject.Find("Frank_Damage_2Handed_Hit");
        var thaAnim = twoHAtk?.GetComponent<Animator>();
        var thvAnim = twoHVic?.GetComponent<Animator>();
        result.Log("2Handed: Atk hips={0}, Vic hips={1}",
            thaAnim?.GetBoneTransform(HumanBodyBones.Hips)?.position,
            thvAnim?.GetBoneTransform(HumanBodyBones.Hips)?.position);

        EditorApplication.isPlaying = false;
        result.Log("Exited play mode.");
    }
}

